#include <vector>

class Solution {
public:
    int sumOfGoodNumbers(std::vector<int>& nums, int k) {
        int n = nums.size();
        int ans = 0;
        for (int i = 0; i < n; ++i) {
            if ((i - k < 0 || nums[i] > nums[i - k]) && (i + k >= n || nums[i] > nums[i + k])) {
                ans += nums[i];
            }
        }
        return ans;
    }
};

class Solution {
